import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    name: string;
    email: string;
    phone: string;
    country: string;
    city: string;
    street: string;
    zip: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');

  const [country, setCountry] = useState('');
  const [city, setCity] = useState('');
  const [street, setStreet] = useState('');
  const [zip, setZip] = useState('');

  const isContactsValid = name.trim().length > 0 && email.includes('@');
  const isAddressValid = country.trim().length > 0 && city.trim().length > 0;

  const canGoNext = step === 0 ? isContactsValid : step === 1 ? isAddressValid : true;

  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));
  const goBack = () => setStep((current) => Math.max(current - 1, 0));

  const submit = () => {
    onSubmit({ name, email, phone, country, city, street, zip });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-lg)',
        maxWidth: 480,
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxInputField
            label="Имя"
            required
            value={name}
            onChange={(event) => setName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            errorText={email.length > 0 && !email.includes('@') ? 'Укажите адрес с символом @' : undefined}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxInputField
            label="Страна"
            required
            value={country}
            onChange={(event) => setCountry(event.target.value)}
          />
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(event) => setCity(event.target.value)}
          />
          <JxInputField
            label="Улица и дом"
            value={street}
            onChange={(event) => setStreet(event.target.value)}
          />
          <JxInputField
            label="Индекс"
            value={zip}
            onChange={(event) => setZip(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <JxDivider label="Контакты" />
          <div style={{ color: 'var(--jx-text-2)' }}>
            <div>Имя: {name || '—'}</div>
            <div>Почта: {email || '—'}</div>
            <div>Телефон: {phone || '—'}</div>
          </div>
          <JxDivider label="Адрес" />
          <div style={{ color: 'var(--jx-text-2)' }}>
            <div>Страна: {country || '—'}</div>
            <div>Город: {city || '—'}</div>
            <div>Улица и дом: {street || '—'}</div>
            <div>Индекс: {zip || '—'}</div>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
        <JxButton variant="ghost" onClick={goBack} disabled={step === 0}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" onClick={goNext} disabled={!canGoNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={submit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

